<template>
  <div class="flex">
    <button @click="addToCart()"
            :class="[isInCart ? 'bg-gray-300 text-gray-700 cursor-not-allowed' : 'bg-orange-500 border-white hover:bg-orange-600 text-white', 'flex items-center justify-center rounded-none px-4 py-2 h-10 transition-colors duration-300 mr-2']"
            :disabled="isInCart">
      <span class="mr-2">
        <font-awesome-icon :icon="isInCart ? 'fa-check' : 'fa-cart-plus'" />
      </span>
      <span>{{ isInCart ? 'In Cart' : 'Add To Cart' }}</span>
    </button>
  
    <button @click="shareOnWhatsapp()"
            class="bg-green-500 border-white hover:bg-green-600 text-white flex items-center justify-center rounded-none px-4 py-2 h-10 transition-colors duration-300">
      <span id="boot-icon" class="bi bi-whatsapp mr-2" style="color: white;"></span>
      <span>Order On Whatsapp</span>
    </button>
  </div>
</template>

<script setup>
import { computed } from 'vue';
import { useCartStore } from '../store/cart.js';
import { toast } from 'vue3-toastify';
import 'vue3-toastify/dist/index.css';

const props = defineProps({
    productId: Number,
    productName: String,
    sellingPrice: Number
});

const store = useCartStore(); // Assign the store directly

const isInCart = computed(() => {
    return store.cart.some(item => item.id === props.productId);
});

function addToCart() {
    if (!isInCart.value) {
        store.addToCart({
            id: props.productId,
            product_name: props.productName,
            selling_price: props.sellingPrice,
            quantity: 1
        });
        toast.success(`${props.productName} added to cart!`);
    }
}

function shareOnWhatsapp() {
    const message = `Hi, I would like to order the ${props.productName}. Here is the link to the product: ${window.location.href}`;
    const whatsappLink = `https://wa.me/+254710909198?text=${encodeURIComponent(message)}`;
    window.open(whatsappLink, '_blank');
}
</script>

<style scoped>
/* Additional custom styles */
button {
  transition: background-color 0.3s, color 0.3s;
}

button:hover {
  filter: brightness(110%);
}

button:focus {
  outline: none;
}

/* Style for WhatsApp icon */
.bi-whatsapp {
  font-size: 1.25rem; /* Adjust icon size */
}
</style>
