<template>
  <div v-for="(item, index) in products" :key="index" class="col-xl-3 col-lg-3 col-sm-6">
                           <div class="tp-product-item p-relative transition-3 mb-25">
                              <div class="tp-product-thumb p-relative fix m-img">

                                <div @click="goToProductDetails(item.slug)">
                                  <img :src="item.product_image" :alt="item.product_name" width="300">
                                </div>
                                                          
                                 
      
                                 <!-- product badge -->
                                 <div class="tp-product-badge">
                                    <span class="product-hot">Hot</span>
                                 </div>
    
                              </div>
                              <!-- product content -->
                              <div class="tp-product-content">
                                 <div class="tp-product-category">
                                    <a href="shop.html">Tablet</a>
                                 </div>
                                 <h3 class="tp-product-title">
                                  <a :href="'/show/product/' + item.slug" class="showcase-category">{{ capitalizeFirstLetter(item.product_name) }}</a>
                                 </h3>
                                 <div class="tp-product-rating d-flex align-items-center">
                                    <div class="tp-product-rating-icon">
                                       <span><i class="fa-solid fa-star"></i></span>
                                       <span><i class="fa-solid fa-star"></i></span>
                                       <span><i class="fa-solid fa-star"></i></span>
                                       <span><i class="fa-solid fa-star"></i></span>
                                       <span><i class="fa-solid fa-star-half-stroke"></i></span>
                                    </div>
                                    <div class="tp-product-rating-text">
                                       <span>(7 Review)</span>
                                    </div>
                                 </div>
                                 <div class="tp-product-price-wrapper">
                                    <span class="tp-product-price old-price">Ksh {{ item.buying_price }}</span>
                                    <span class="tp-product-price new-price">Ksh {{ item.selling_price }}</span>
                                 </div>
                              </div>
                              <CartButton :product="item"/>
                           </div>
                           <!-- <CartBTN :productId="item.id"/> -->
        
        <!-- <WhatsappButton :productName="item.product_name"/> -->
                        </div>
</template>

<script>
import axios from 'axios';
import CartButton from './CartButton.vue';
import { toast } from 'vue3-toastify';
import 'vue3-toastify/dist/index.css';

export default {
  components: {
    CartButton,
    // Import toast-container
    'toast-container': toast.ToastContainer
  },
  props: {
    productDetailsUrl: String,
  },
  data() {
    return {
      products: [],
      buttonLabel: '',
    };
  },
  mounted() {
    // Display toast message when fetching products
    this.showToast('Shop is Populating. Please be patient.');
    this.fetchProducts();
  },
  methods: {
    fetchProducts() {
    axios.get('/api/foxtrot/products')
      .then(response => {
        if (response.data && Array.isArray(response.data.products)) {
          // Shuffle the products array
          const shuffledProducts = response.data.products.sort(() => Math.random() - 0.5);
          // Take the first 15 items
          this.products = shuffledProducts.slice(0, 15).map(product => {
            return { ...product };
          });
        } else {
          console.error('Invalid response format:', response);
        }
      })
      .catch(error => {
        console.error('Error fetching products:', error);
      });
  },
    goToProductDetails(slug) {
      const url = this.productDetailsUrl.replace(':slug', slug);
      window.location.href = url;
    },
    // Function to show toast message
    showToast(message) {
      toast.info(message);
    },
    capitalizeFirstLetter(str) {
    return str.toLowerCase().replace(/\b\w/g, function (char) {
      return char.toUpperCase();
    });
  }
  },
};
</script>
