<script>
import { toast } from 'vue3-toastify';
import 'vue3-toastify/dist/index.css';
export default {
  data() {
    return {
      cart: []
    };
  },
  created() {
    // Retrieve cart data from local storage on component creation
    const storedCart = JSON.parse(localStorage.getItem('cart'));
    if (storedCart) {
      this.cart = storedCart;
    }
  },
  computed: {
    totalItems() {
      return this.cart.reduce((total, item) => total + item.quantity, 0);
    },
    subtotal() {
      return this.cart.reduce((total, item) => total + (item.selling_price * item.quantity), 0);
    }
  },
  methods: {
    incrementQuantity(index) {
  const item = this.cart[index];
  if (item.quantity === 9) {
    // Apply discount to 1500 if the quantity is 10
    item.selling_price = 1500;
    toast.info('Discount applied: Selling price is now 1500');
  } else if (item.quantity === 99) {
    // Apply discount to 1300 if the quantity is 100
    item.selling_price = 1300;
    toast.info('Discount applied: Selling price is now 1300');
  }
  item.quantity++;
  this.updateCart();
  toast.success('Quantity increased successfully');
},
    decrementQuantity(index) {
      if (this.cart[index].quantity > 1) {
        this.cart[index].quantity--;
        this.updateCart();
        toast.success('Quantity decreased successfully');
      } else {
        toast.error('Quantity cannot be less than 1');
      }
    },
    removeItem(index) {
      this.cart.splice(index, 1);
      this.updateCart();
      toast.success('Item removed from cart');
    },
    updateCart() {
      localStorage.setItem('cart', JSON.stringify(this.cart));
    },
    checkout() {
      // Implement checkout functionality here
      this.$router.push('/checkout');
    },
    applyCoupon() {
  // Check if the coupon has already been applied
  if (this.couponApplied) {
    toast.error('Coupon has already been applied');
    return;
  }
  
  // Convert the promo code to uppercase
  const promoCodeUpperCase = this.promoCode.toUpperCase();

  // Check if promo code is valid
  if (promoCodeUpperCase === 'WABE' || promoCodeUpperCase ==='AMORE') {
    // Apply discount to each item in the cart
    this.cart.forEach(item => {
      item.selling_price *= 0.83333333333; // Apply 20% discount
      item.selling_price = Math.round(item.selling_price / 10) * 10; // Round off to the nearest 10
      
      // If the decimal part is greater than or equal to 0.5, round up; otherwise, round down
      if ((item.selling_price % 10) >= 5) {
        item.selling_price = Math.ceil(item.selling_price / 10) * 10; // Round up to the nearest 10
      } else {
        item.selling_price = Math.floor(item.selling_price / 10) * 10; // Round down to the nearest 10
      }
    });
    this.updateCart();
    toast.success('Promo code applied successfully');
    this.couponApplied = true; // Set flag to true
    localStorage.setItem('couponApplied', 'true'); // Store coupon status in local storage
    
    // Store the coupon code in local storage
    localStorage.setItem('couponCode', promoCodeUpperCase);
  } else {
    toast.error('Invalid promo code');
  }
}
  }
};
</script>

