<script>
export default {
  props: {
    blog: {
      type: Object,
      required: true
    }
  },
  methods: {
    getImageUrl(url) {
      console.log("Original URL:", url); // Log the original URL
      // Check if the URL contains '/show/blog/'
      const prefixIndex = url.indexOf('/show/blog/');
      if (prefixIndex !== -1) {
        // If it contains the prefix, remove it
        const cleanUrl = url.substring(prefixIndex + '/show/blog/'.length);
        console.log("Clean URL:", cleanUrl); // Log the clean URL
        return cleanUrl;
      } else {
        // If it doesn't contain the prefix, return the URL as is
        return url;
      }
    },
    openModal() {
      const modal = document.getElementById("myModal");
      modal.style.display = "block";
    },
    closeModal() {
      const modal = document.getElementById("myModal");
      modal.style.display = "none";
    }
  }
}
</script>

