<template>
    <button class="whatsapp-button" @click="openWhatsApp">
      <span id="boot-icon" class="bi bi-whatsapp" style="color: rgb(255, 255, 255);"></span>
    </button>
  </template>
  
  <script setup>
  import { defineProps } from 'vue';
  
  const props = defineProps({
    productName: String
  });
  
  const openWhatsApp = () => {
    const phoneNumber = '+254710909198';
    const message = encodeURIComponent(`Hi Foxtrot, I would like to Buy the ${props.productName}.`);
    const whatsappUrl = `https://wa.me/${phoneNumber}?text=${message}`;
    window.open(whatsappUrl, '_blank');
  };
  </script>
  
  <style scoped>
.whatsapp-button {
  width: 40px; /* Adjust size as needed */
  height: 40px; /* Adjust size as needed */
  background-color: #25D366; /* WhatsApp green color */
  border: none;
  border-radius: 5px;
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  transition: background-color 0.3s; /* Add transition effect */
}

.whatsapp-button:hover {
  background-color: #128C7E; /* Alternative WhatsApp color on hover */
}

.whatsapp-icon {
  color: white; /* Set the color of the icon to white */
  font-size: 24px; /* Adjust size as needed */
}
</style>
  