<template>

  
  <div class="font-[sans-serif] bg-white">
    <div class="max-lg:max-w-xl mx-auto w-full px-4"> <!-- Add padding to the container -->
      <div class="grid lg:grid-cols-3 gap-6">
        <div class="lg:col-span-2 max-w-4xl mx-auto w-full">
          <div class="text-center max-lg:hidden">
            <h2 class="text-3xl font-extrabold text-[#333] inline-block border-b-4 border-[#333] pb-1">Checkout</h2>
          </div>

          

          

          
          <div v-if="cart.length > 0"> <!-- Render the checkout form only if the cart is not empty -->
            <form class="lg:mt-12" @submit.prevent="submitOrder">
              <h2 class="text-2xl font-extrabold text-[#333] mt-16">Billing Details</h2>
              <div class="grid grid-cols-2 gap-6 mt-8">
                <input v-model="formData.customer_name" type="text" placeholder="Name" class="px-2 py-3.5 bg-white text-[#333] w-full text-sm border-b-2 focus:border-[#333] outline-none"/>
                <input v-model="formData.customer_email" type="email" placeholder="Email address" class="px-2 py-3.5 bg-white text-[#333] w-full text-sm border-b-2 focus:border-[#333] outline-none"/>
                <input type="text" v-model="formData.customer_phone" placeholder="Phone Number" class="px-2 py-3.5 bg-white text-[#333] w-full text-sm border-b-2 focus:border-[#333] outline-none" />
                <textarea v-model="formData.customer_address" placeholder="Where to Deliver" class="px-2 py-3.5 bg-white text-[#333] w-full text-sm border-b-2 focus:border-[#333] outline-none"></textarea>
                <textarea v-model="formData.customer_notes" placeholder="Any Special Instructions" class="px-2 py-3.5 bg-white text-[#333] w-full text-sm border-b-2 focus:border-[#333] outline-none"></textarea>
                
              </div>
              <!-- Payment Options -->
              <div class="mt-8">
                <label for="paymentMethod" class="block text-sm font-medium text-gray-700">Payment Method</label>
                <select v-model="formData.payment_status" id="paymentMethod" name="paymentMethod" class="mt-1 block w-full py-2 px-3 border border-gray-300 bg-white rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm">
                  <option class="active" value="mpesa">Mpesa</option>
                </select>
              </div>
              <div v-if="formErrors && formErrors.length > 0" class="mt-4">
                <ul class="text-red-500">
                  <li v-for="error in formErrors" :key="error">{{ error }}</li>
                </ul>
              </div>
              <div class="flex flex-wrap gap-4 mt-8">
                <button type="submit" :disabled="processing" class="min-w-[150px] px-6 py-3.5 text-sm bg-[#333] text-white rounded-md hover:bg-[#111]">
                  <span v-if="processing">Processing Order...</span>
                  <span v-else>Place Order</span>
                </button>
              </div>
            </form>
          </div>
          <div v-else> <!-- Render a message when the cart is empty -->
            <h3 class="text-2xl font-extrabold text-[#333] mt-16">Your cart is empty. Add some products to proceed with the checkout.</h3>
          </div>
        </div>
        <div class="bg-gray-100 lg:h-screen lg:sticky lg:top-0">
          <div class="relative h-full">
            <div class="p-8 lg:overflow-auto lg:h-[calc(100vh-60px)] max-lg:mb-8">
              <h2 class="text-2xl font-extrabold text-[#333]">Order Summary</h2>
              <div class="space-y-6 mt-10">
                <div v-for="(item, index) in cart" :key="index" class="grid sm:grid-cols-2 items-start gap-6">
                  <div class="max-w-[190px] px-4 py-6 shrink-0 bg-gray-200 rounded-md">
                    <img :src="item.product_image" class="w-full object-contain" />
                  </div>
                  <div>
                    <h3 class="text-base text-[#333]">{{ item.product_name }}</h3>
                    <ul class="text-xs text-[#333] space-y-2 mt-2">
                      <li>Size <span class="float-right">{{ item.size }}</span></li>
                      <li>Quantity <span class="float-right">{{ item.quantity }}</span></li>
                      <li>Total Price <span class="float-right">{{ item.selling_price * item.quantity }}</span></li>
                    </ul>
                  </div>
                </div>
              </div>
            </div>
            <div class="absolute left-0 bottom-0 bg-gray-200 w-full p-4">
              <h4 class="flex flex-wrap gap-4 text-base text-[#333] font-bold">Total <span class="ml-auto">{{ calculateTotal() }}</span></h4>
            </div>
          </div>
        </div>
      </div>
    </div>
   
    <!-- Order Success Modal -->
    <OrderSuccessModal :orderId="orderId" :showModal="orderSuccessModalVisible" @close="orderSuccessModalVisible = false" />
  </div>

    
</template>

<script>
import axios from 'axios'; // Import Axios if you haven't already
import { toast } from 'vue3-toastify'; // Import toast from vue3-toastify
import OrderSuccessModal from '../components/OrderSuccessModal.vue'; // Import OrderSuccessModal component

export default {
  components: {
    OrderSuccessModal, // Register OrderSuccessModal comp
  },
  data() {
    return {
      orderId: null, // Initialize orderId to null
      orderPlaced: false, // Boolean to track if the order is placed
      formErrors: [], // Added formErrors array
      formData: {
        customer_name: '',
        customer_email: '',
        customer_address: '',
        customer_phone: '',
        payment_status: 'cash', // Default to Cash On Delivery
        cart_contents: [], // Initialize cart contents array
      },
      cart: [],
      processing: false,
      orderSuccessModalVisible: false, // Add this variable
      authenticatedClient: null, // To store authenticated client data
    };
  },
  created() {
    // Retrieve cart data from local storage on component creation
    const storedCart = JSON.parse(localStorage.getItem('cart'));
    const couponApplied = localStorage.getItem('couponApplied');
    const couponCode = localStorage.getItem('couponCode');
    // Use the coupon information as needed
    if (couponApplied === 'true') {
      // Coupon has been applied
      console.log('Coupon applied:', couponCode);
      // Store the coupon code in the formData object
      this.formData.coupon_code = couponCode;
    } else {
      // Coupon has not been applied
      console.log('No coupon applied');
    }

    if (storedCart) {
      this.cart = storedCart;
      console.log('Cart Data:', this.cart); // Log cart data
    }

    // Check if the client is logged in and retrieve their name and email if logged in
    this.checkLoggedIn();
  },
  methods: {
    async checkLoggedIn() {
      try {
        const response = await axios.get('/api/check-authentication'); // Adjust the endpoint accordingly
        if (response.data.success) {
          // User is logged in
          this.authenticatedClient = response.data.client; // Store authenticated client data
          this.formData.customer_name = response.data.client.name; // Set customer name from authenticated client data
          this.formData.customer_email = response.data.client.email; // Set customer email from authenticated client data
        }
      } catch (error) {
        console.error('Error checking authentication:', error);
      }
    },
    async submitOrder() {
      this.formErrors = []; // Reset form errors before validation
      
      if (!this.validateForm()) {
        return; // Exit if form validation fails
      }
      try {
        // Fetch CSRF token from meta tag
        const csrfToken = document.querySelector('meta[name="csrf-token"]').getAttribute('content');
        // Include CSRF token in form data
        this.formData._token = csrfToken;
        // Directly assign cart contents to formData
        this.formData.cart_contents = this.cart.map(item => {
          return {
            id: item.id,
            name: item.product_name,
            price: item.selling_price,
            quantity: item.quantity
          };
        });
        // Include payment method data when submitting the order
        this.formData.total_products = this.calculateCartCount(); // Add cart count to formData
        this.formData.total_amount = this.calculateTotal(); // Add total amount to formData
        // Change button text to "Processing Order..."
        this.processing = true;
        // Send POST request to backend with CSRF token included
        const response = await axios.post('/final-invoice', this.formData);
        if (response.data.success) {
          // Show the order success modal
          this.orderSuccessModalVisible = true;
        } else {
          // Show an error message if the order was not placed successfully
          toast.error(response.data.message);
          this.orderPlaced = true; // Set orderPlaced to true to show the modal
        }
      } catch (error) {
        // Show an error message if there was a problem with the server request
        toast.error('There was a problem with your order. Please try again later.');
      } finally {
        // Reset button text to "Place Order" after processing
        this.processing = false;
      }
    },
    validateForm() {
      let isValid = true;
      // Check each form field for validation
      if (!this.formData.customer_name.trim()) {
        this.formErrors.push('Name is required.');
        isValid = false;
      }
      if (!this.formData.customer_email.trim()) {
        this.formErrors.push('Email is required.');
        isValid = false;
      } else if (!this.isValidEmail(this.formData.customer_email.trim())) {
        this.formErrors.push('Invalid email address.');
        isValid = false;
      }
      if (!this.formData.customer_phone.trim()) {
        this.formErrors.push('Phone number is required.');
        isValid = false;
      } else if (!this.isValidPhoneNumber(this.formData.customer_phone.trim())) {
        this.formErrors.push('Invalid phone number, Check and Try again.');
        isValid = false;
      }
      // Add more validation checks for other fields as needed...
      return isValid;
    },
    isValidEmail(email) {
      // Email validation logic (you can use a regular expression or any library)
      // For example, a simple regex pattern:
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    },
    isValidPhoneNumber(phone) {
    // Adjusted regex pattern for Kenyan phone numbers starting with "+254", "254", or "0"
    // Allows for variations like "+254712345678", "254712345678", or "0712345678"
    return /^(?:\+254|254|0)?\d{9}$/.test(phone);
},
    calculateTotal() {
      return this.cart.reduce((total, item) => total + (item.selling_price * item.quantity), 0);
    },
    calculateCartCount() {
      return this.cart.reduce((count, item) => count + item.quantity, 0);
    },
    redirectToOrderPage() {
      // Redirect to the order success page
      // You can use window.location.href or Vue Router for navigation
    }
  }
};
</script>

